<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfile;

/**
 * @template-extends ArrayIterator<int, UserProfile>
 */
class UserProfileSlide extends \ArrayIterator
{
    private readonly ?UserProfile $last;
    private readonly UserProfileCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?UserProfileCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor;
        $last = $this->last;
        $this->nextCursor = new UserProfileCursor(
            limit: null === $cursor ? 1000 : $cursor->limit(),
            sinceUid: null == $last ? null : $last->uid(),
        );
    }
    public function cursor(): ?UserProfileCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): UserProfileCursor
    {
        return $this->nextCursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?UserProfile
    {
        return parent::current();
    }
    public function map(\Closure $fn): UserProfileSlide
    {
        return new UserProfileSlide($this->next, $this->cursor, array_map($fn, $this->values));
    }
    public function slide(\Closure $fn): UserProfileSlide
    {
        $filtered = array_filter($this->values, $fn);
        $collected = $filtered;
        $last = $this->last;
        $next = $this->next;
        $cursor = $this->cursor;
        if (null !== $cursor && count($collected) == $cursor->limit()) {
            while (count($collected) < count($this->values) && $next !== null) {
                if ($last === null) {
                    break;
                }
                $nextSlide = $next($this, $cursor->next($last, $cursor->limit()));
                if (count($nextSlide)) {
                    $nextFiltered = array_filter($nextSlide->values, $fn);
                    $collected = array_merge($collected, $nextFiltered);
                    $cursor = $nextSlide->cursor;
                    $next = $nextSlide->next;
                    $last = $nextSlide->last;
                } else {
                    break;
                }
            }
            return new UserProfileSlide($next, $cursor, $collected);
        } else {
            return $this;
        }
    }
}
